/**
 * Zoho CRM transport.
 *
 * Pattern lifted from incquet-dev/IQHDM-Task-Execution-widget, which is the proven
 * working widget in this org: CRM widget (plugin-manifest {"service":"CRM"}), registered
 * as a Web Tab with External hosting, talking over the logged-in user's OAuth session.
 * No apikey, no zapikey, no CORS problem, no middleware.
 *
 *   ZOHO.embeddedApp.on("PageLoad", cb) → ZOHO.embeddedApp.init()
 *   ZOHO.CRM.API.coql({select_query})            reads
 *   ZOHO.CRM.CONFIG.getCurrentUser()             identity
 *   ZOHO.CRM.META.getCustomViews({Entity})       the real pool filters, at runtime
 *   ZOHO.CRM.CONNECTION.invoke('iq_crm', {...})  escape hatch: aggregates, v8 endpoints
 *
 * Aggregate COQL (`select COUNT(id) …`) does NOT work through API.coql — Incquet routes
 * it through CONNECTION.invoke against /crm/v6/coql. Same here.
 */

import { traced, note } from './diag.js';

export const CONNECTION = 'iq_crm';

/**
 * The vendored SDK touches `window` at module scope, so it is imported lazily rather
 * than at the top of this file. That keeps calc/data/roles importable from Node (see
 * test.mjs) and means the SDK only loads when we're actually going to talk to Zoho.
 */
let sdkPromise = null;
export function sdk() {
  if (!sdkPromise) sdkPromise = import('./lib/zohocrmsdk.js').then((m) => m.ZOHO);
  return sdkPromise;
}

/** Are we inside a Zoho iframe, or standalone (local dev / GitHub Pages direct hit)? */
export const inZoho = () => {
  if (typeof window === 'undefined') return false;
  try {
    return window.self !== window.top;
  } catch {
    return true; // cross-origin access threw ⇒ we're framed
  }
};

let ready = null;
let diagReady = false;

/** Resolves once Zoho has handed us the page context. Never rejects — see boot(). */
export function whenReady() {
  if (ready) return ready;
  ready = sdk().then(
    (ZOHO) =>
      new Promise((resolve, reject) => {
        // Record exactly what Zoho handed us before touching the SDK, so a failed
        // handshake is diagnosable from the Connection panel rather than the console.
        try {
          const p = Object.fromEntries(new URLSearchParams(location.search));
          note({ params: p, href: location.href });
        } catch { /* non-fatal */ }

        try {
          ZOHO.embeddedApp.on('PageLoad', (data) => {
            diagReady = true;
            note({ sdkReady: true });
            resolve(data ?? {});
          });
          // Throws if serviceOrigin is absent — postMessage rejects an undefined target
          // origin, `new ZSDK` propagates it, and the SDK is left half-constructed.
          ZOHO.embeddedApp.init();
        } catch (e) {
          note({ sdkError: e?.message || String(e) });
          reject(e);
        }
      })
  );
  ready.catch(() => {}); // keep the shared promise from surfacing as unhandled
  return ready;
}

/**
 * True only once Zoho has completed the handshake. Every CRM read is gated on this —
 * calling ZOHO.CRM.* before PageLoad throws an error that reads like a bug in our query
 * when it is really the SDK not being ready.
 */
export function sdkIsReady() {
  return diagReady;
}

/* ------------------------------------------------------------------ reads */

export async function coql(selectQuery) {
  return traced('COQL', selectQuery, async () => {
    if (!diagReady) {
      throw new Error(
        'Zoho SDK handshake never completed — no CRM call can succeed. ' +
          'Check the serviceOrigin param in the Connection panel.'
      );
    }
    const ZOHO = await sdk();
    const resp = await ZOHO.CRM.API.coql({ select_query: selectQuery });
    // Zoho signals query errors in the body as often as by rejecting.
    if (resp?.status === 'error' || resp?.code) {
      throw new Error(resp.message || resp.code || 'COQL error');
    }
    return { rows: resp?.data ?? [], info: resp?.info ?? {} };
  });
}

/**
 * COUNT via the named connection. Returns 0 rather than throwing — a badge that fails
 * to load must never take the page down with it.
 */
export async function coqlCount(selectQuery) {
  try {
    const ZOHO = await sdk();
    const resp = await ZOHO.CRM.CONNECTION.invoke(CONNECTION, {
      method: 'POST',
      url: 'https://www.zohoapis.com/crm/v6/coql',
      parameters: { select_query: selectQuery },
    });
    if (resp?.status === 'success' && resp.details?.status === 'true') {
      return Number(resp.details?.statusMessage?.data?.[0]?.['COUNT(id)']) || 0;
    }
    return 0;
  } catch (e) {
    console.error('coqlCount failed:', selectQuery, e);
    return 0;
  }
}

export async function currentUser() {
  return traced('getCurrentUser', 'CONFIG.getCurrentUser', async () => {
    const ZOHO = await sdk();
    const data = await ZOHO.CRM.CONFIG.getCurrentUser();
    const u = data?.users?.[0] ?? null;
    note({ user: u ? { name: u.full_name, email: u.email, profile: u.profile?.name, role: u.role?.name } : null });
    return u;
  });
}

/** Org identity — proves which CRM we're actually talking to. */
export async function orgInfo() {
  try {
    return await traced('getOrgInfo', 'CONFIG.getOrgInfo', async () => {
      const ZOHO = await sdk();
      const data = await ZOHO.CRM.CONFIG.getOrgInfo();
      const o = data?.org?.[0] ?? data?.data?.[0] ?? null;
      note({ org: o ? { name: o.company_name, id: o.zgid || o.id } : null });
      return o;
    });
  } catch (e) {
    console.warn('org info unavailable', e);
    return null;
  }
}

/**
 * The real filter criteria behind the three deal pools, straight from CRM.
 * We have never confirmed the pool definitions from the export — this reads them at
 * runtime instead of guessing. See FINDINGS.md §5.
 */
export async function customViews(entity = 'Deals') {
  const ZOHO = await sdk();
  const resp = await ZOHO.CRM.META.getCustomViews({ Entity: entity });
  return resp?.custom_views ?? resp?.data?.custom_views ?? [];
}

export async function fields(entity = 'Deals') {
  const ZOHO = await sdk();
  const resp = await ZOHO.CRM.META.getFields({ Entity: entity });
  return resp?.fields ?? resp?.data?.fields ?? [];
}

/* ------------------------------------------------------------------ writes */

/**
 * Every write funnels through here so there is exactly ONE place that can be switched
 * on, and exactly one place to audit.
 *
 * Writes are OFF for the first review build (Trevor, 19 Jul). Reads are live; anything
 * that mutates CRM returns a description of what it *would* do.
 *
 * The lock path in particular is loud: automation.finalizeTranche5 sets
 * Avail_for_Purchase=false on every deal in the tranche, flips Tranche_Status to
 * "Locked", emails three Investor Relations recipients, and snapshots to Tranche_Logs +
 * Deal_Logs. Not something to fire during a demo.
 */
export const WRITES_ENABLED = false;

export async function write(description, fn) {
  if (!WRITES_ENABLED) {
    console.info('[write suppressed]', description);
    return { suppressed: true, description };
  }
  const result = await fn();
  return { suppressed: false, description, result };
}

/**
 * Create Tranche is the ONE write turned on (Trevor, approved). Lock stays simulated —
 * finalizeTranche5 emails three people. Scoped hard to test records below.
 */
export const TRANCHE_CREATE_WRITES = true;

/**
 * Create a REAL tranche in CRM and assign the given deals to it.
 *
 * HARD GUARD: refuses if ANY selected deal is not a test record. The widget must never
 * mutate a real customer deal. This runs only from sandbox mode (which shows only test
 * deals), so this is the belt over that suspenders.
 *
 * Request shape matches Incquet's working widget: flat APIData `{ id, ...fields }`,
 * Trigger ['workflow'], success = resp.data[0].code === 'SUCCESS'. Module api_name is
 * `Tranches` (COQL confirmed; `CustomModule8` is INVALID_MODULE for the API).
 */
export async function createTrancheLive({ name, investorId, trancheDate, deals }) {
  const nonTest = deals.filter((d) => d.Test_Record !== true);
  if (nonTest.length) {
    throw new Error(
      `Refusing to write — ${nonTest.length} selected deal(s) are not test records. ` +
        `Create only ever writes test deals.`
    );
  }
  const ZOHO = await sdk();

  const ins = await traced('insertRecord', `Tranches "${name}"`, () =>
    ZOHO.CRM.API.insertRecord({
      Entity: 'Tranches',
      APIData: {
        Name: name,
        Investor: { id: String(investorId) },
        Tranche_Status: 'Open',
        Tranche_Date: trancheDate,
      },
      Trigger: ['workflow'],
    })
  );
  const first = ins?.data?.[0];
  if (first?.code !== 'SUCCESS') {
    throw new Error('Tranche create failed: ' + (first?.message || JSON.stringify(ins).slice(0, 200)));
  }
  const trancheId = first.details?.id;

  const assigned = [];
  const errors = [];
  for (const d of deals) {
    try {
      const resp = await traced('updateRecord', `Deal ${d.id} → Tranche`, () =>
        ZOHO.CRM.API.updateRecord({
          Entity: 'Deals',
          APIData: { id: String(d.id), Tranche: { id: String(trancheId) } },
          Trigger: ['workflow'],
        })
      );
      if (resp?.data?.[0]?.code === 'SUCCESS') assigned.push(String(d.id));
      else errors.push({ id: d.id, error: resp?.data?.[0]?.message || 'update not successful' });
    } catch (e) {
      errors.push({ id: d.id, error: e?.message || String(e) });
    }
  }
  return { trancheId, name, assigned, errors };
}

/**
 * Undo a tranche the widget created this session: un-assign its deals (Tranche → null, so
 * they return to the pool) and delete the tranche record. Only ever called on the widget's
 * own freshly-created tranches with their known test deals — never arbitrary CRM records.
 */
export async function undoTrancheLive({ trancheId, dealIds }) {
  const ZOHO = await sdk();
  const cleared = [];
  const errors = [];
  for (const id of dealIds) {
    try {
      const resp = await traced('updateRecord', `Deal ${id} → un-assign tranche`, () =>
        ZOHO.CRM.API.updateRecord({ Entity: 'Deals', APIData: { id: String(id), Tranche: null }, Trigger: ['workflow'] })
      );
      if (resp?.data?.[0]?.code === 'SUCCESS') cleared.push(String(id));
      else errors.push({ id, error: resp?.data?.[0]?.message || 'update not successful' });
    } catch (e) {
      errors.push({ id, error: e?.message || String(e) });
    }
  }
  try {
    await traced('deleteRecord', `Tranches ${trancheId}`, () =>
      ZOHO.CRM.API.deleteRecord({ Entity: 'Tranches', RecordID: String(trancheId) })
    );
  } catch (e) {
    errors.push({ id: trancheId, error: 'tranche delete failed: ' + (e?.message || String(e)) });
  }
  return { cleared, errors };
}

/* ---------------------------------------------------------------- swaps */

/**
 * The two CRM Accounts safe to write pricing for. Every pricing write is refused unless the
 * investor is one of these — the belt over the sandbox-only suspenders.
 *   Solar Power Investments LLC Demo · Test Account Fund
 */
export const TEST_INVESTOR_IDS = ['3089744000033883248', '3089744000000167456'];

/** Swaps are the ONE further write turned on beyond Create, and only on test deals. */
export const TRANCHE_SWAP_WRITES = true;

/**
 * Swap deals in/out of a tranche the widget created this session.
 *
 * Two CRM effects, because the swap record does NOT move deals by itself (verified: zero
 * workflow rules on Tranche_Swap_Records — it is a ledger/document artifact):
 *   1. Insert a Tranche_Swap_Records row: Associated_Tranche → the tranche, the out-deals in
 *      the Deals_to_be_swapped subform (lookup Original_Deal_Sold), the in-deals in
 *      Deals_Swapped_in (lookup Deals_Used_for_Swaps).
 *   2. Actually move the deals: each out-deal Tranche → null + Avail_for_Purchase → true (so
 *      it returns to the pool, mirroring removeFromTranche); each in-deal Tranche → the
 *      tranche (which fires updtTranche to re-sum totals).
 *
 * HARD GUARD: refuses if any deal is not a test record. Never touches a real customer deal.
 */
export async function swapTrancheLive({ trancheId, trancheName, dealsOut, dealsIn, swapDate }) {
  const all = [...dealsOut, ...dealsIn];
  const nonTest = all.filter((d) => d.Test_Record !== true);
  if (nonTest.length) {
    throw new Error(`Refusing to swap — ${nonTest.length} deal(s) are not test records.`);
  }
  const ZOHO = await sdk();
  const date = swapDate || new Date().toISOString().slice(0, 10);

  const outRow = (d) => ({
    Original_Deal_Sold: { id: String(d.id) },
    Date_Swapped_Out: date,
    Amount: d.Amount ?? null,
    Pre_Pay_of_Statement_of_Work: d.Pre_Pay_Pct_of_Statement_of_Work != null ? String(d.Pre_Pay_Pct_of_Statement_of_Work) : null,
    Advance_Payment_Paid: 'No',
  });
  const inRow = (d) => ({
    Deals_Used_for_Swaps: { id: String(d.id) },
    Swap_Date: date,
    Amount: d.Amount ?? null,
    Pre_Pay_of_Statement_of_Work: d.Pre_Pay_Pct_of_Statement_of_Work != null ? String(d.Pre_Pay_Pct_of_Statement_of_Work) : null,
  });

  const ins = await traced('insertRecord', `Tranche_Swap_Records "${trancheName}"`, () =>
    ZOHO.CRM.API.insertRecord({
      Entity: 'Tranche_Swap_Records',
      APIData: {
        Name: `Swap ${date} ${trancheName}`.slice(0, 120),
        Associated_Tranche: { id: String(trancheId) },
        Deals_to_be_swapped: dealsOut.map(outRow),
        Deals_Swapped_in: dealsIn.map(inRow),
      },
      Trigger: ['workflow'],
    })
  );
  const first = ins?.data?.[0];
  if (first?.code !== 'SUCCESS') {
    throw new Error('Swap record create failed: ' + (first?.message || JSON.stringify(ins).slice(0, 200)));
  }
  const swapId = first.details?.id;

  const movedOut = [];
  const movedIn = [];
  const errors = [];
  for (const d of dealsOut) {
    try {
      const resp = await traced('updateRecord', `Deal ${d.id} → out of tranche`, () =>
        ZOHO.CRM.API.updateRecord({
          Entity: 'Deals',
          APIData: { id: String(d.id), Tranche: null, Avail_for_Purchase: true },
          Trigger: ['workflow'],
        })
      );
      if (resp?.data?.[0]?.code === 'SUCCESS') movedOut.push(String(d.id));
      else errors.push({ id: d.id, error: resp?.data?.[0]?.message || 'out update failed' });
    } catch (e) { errors.push({ id: d.id, error: e?.message || String(e) }); }
  }
  for (const d of dealsIn) {
    try {
      const resp = await traced('updateRecord', `Deal ${d.id} → into tranche`, () =>
        ZOHO.CRM.API.updateRecord({
          Entity: 'Deals',
          APIData: { id: String(d.id), Tranche: { id: String(trancheId) } },
          Trigger: ['workflow'],
        })
      );
      if (resp?.data?.[0]?.code === 'SUCCESS') movedIn.push(String(d.id));
      else errors.push({ id: d.id, error: resp?.data?.[0]?.message || 'in update failed' });
    } catch (e) { errors.push({ id: d.id, error: e?.message || String(e) }); }
  }
  return { swapId, movedOut, movedIn, errors };
}

/* ---------------------------------------------------------------- pricing writes */

/** Pricing writes are ON but scoped to the two test investor accounts only. */
export const PRICING_WRITES = true;

/**
 * Save a Bill-of-Sale rate to CRM for a TEST investor, into one of the five fixed
 * Investor_Pricing_Matrix cells (column). Creates the investor's Investor_Pricing record on
 * first use (the two test accounts have none), then read-modify-writes the whole matrix
 * subform (Zoho replaces the entire subform — any omitted row is deleted).
 *
 * HARD GUARD: refuses any account that is not one of the two test investors.
 *
 * @param {string} column one of EC_Pricing_75_40 | EC_Pricing_76_40 | EC_Pricing_77_40 |
 *                        EC_Pricing_pend_50 | Non_EC_Pricing_80_30
 * @param {number} value  raw decimal Bill-of-Sale % (0.655), NOT ×100
 */
export async function saveInvestorRateLive({ accountId, state, product, column, value, year }) {
  if (!TEST_INVESTOR_IDS.includes(String(accountId))) {
    throw new Error('Refusing to write pricing — investor is not a test account.');
  }
  const ZOHO = await sdk();
  const yr = year || String(new Date().getFullYear());

  // 1. Find (or create) the investor's Active pricing record.
  let recordId = null;
  let created = false;
  const q = await traced('COQL', 'Investor_Pricing for test account', () =>
    ZOHO.CRM.API.coql({
      select_query:
        `select id from Investor_Pricing where (Investor = '${accountId}' and Investor_Pricing_Status = 'Active') limit 1`,
    })
  );
  recordId = q?.data?.[0]?.id ?? null;

  if (!recordId) {
    const ins = await traced('insertRecord', `Investor_Pricing (new, test acct ${accountId})`, () =>
      ZOHO.CRM.API.insertRecord({
        Entity: 'Investor_Pricing',
        APIData: {
          Investor: { id: String(accountId) },
          Pricing_Year: yr,
          Investor_Pricing_Status: 'Active',
          Investor_Pricing_Matrix: [{ State: state, HDM_Product: product, [column]: value }],
        },
        Trigger: ['workflow'],
      })
    );
    const first = ins?.data?.[0];
    if (first?.code !== 'SUCCESS') {
      throw new Error('Investor_Pricing create failed: ' + (first?.message || JSON.stringify(ins).slice(0, 200)));
    }
    return { recordId: first.details?.id, created: true, cell: { state, product, column, value } };
  }

  // 2. Existing record → read-modify-write the whole matrix.
  const full = (await traced('getRecord', `Investor_Pricing ${recordId}`, () =>
    ZOHO.CRM.API.getRecord({ Entity: 'Investor_Pricing', RecordID: String(recordId) })
  ))?.data?.[0];
  if (!full) throw new Error('pricing record vanished between read and write');

  const matrix = (full.Investor_Pricing_Matrix ?? []).map((r) => {
    // Strip Zoho system keys; keep `id` so existing rows update rather than duplicate.
    const { $field_states, $layout_id, $in_merge, Parent_Id, Created_Time, ...clean } = r;
    return clean;
  });
  const existing = matrix.find((r) => r.State === state && r.HDM_Product === product);
  if (existing) existing[column] = value;
  else matrix.push({ State: state, HDM_Product: product, [column]: value });

  const upd = await traced('updateRecord', `Investor_Pricing ${recordId} matrix`, () =>
    ZOHO.CRM.API.updateRecord({
      Entity: 'Investor_Pricing',
      APIData: { id: String(recordId), Investor_Pricing_Matrix: matrix },
      Trigger: ['workflow'],
    })
  );
  if (upd?.data?.[0]?.code !== 'SUCCESS') {
    throw new Error('Investor_Pricing matrix update failed: ' + (upd?.data?.[0]?.message || 'unknown'));
  }
  return { recordId: String(recordId), created, cell: { state, product, column, value } };
}

/**
 * Save an investor's WHOLE pricing matrix to CRM in one write — the in-widget editor's save.
 * Creates the Investor_Pricing record if the investor has none (test accounts start empty),
 * otherwise replaces the matrix subform with the edited rows. Rows without an `id` are added;
 * rows present before but absent now are deleted (Zoho replaces the whole subform).
 *
 * HARD GUARD: test investors only.
 */
export async function saveInvestorMatrixLive({ accountId, recordId, year, rows }) {
  if (!TEST_INVESTOR_IDS.includes(String(accountId))) {
    throw new Error('Refusing to write pricing — investor is not a test account.');
  }
  const ZOHO = await sdk();
  const yr = year || String(new Date().getFullYear());
  const cols = ['EC_Pricing_75_40', 'EC_Pricing_76_40', 'EC_Pricing_77_40', 'EC_Pricing_pend_50', 'Non_EC_Pricing_80_30'];
  const matrix = rows.map((r) => {
    const out = { State: String(r.State || '').trim(), HDM_Product: r.HDM_Product };
    if (r.id) out.id = String(r.id);
    for (const c of cols) out[c] = Number(r[c]) || 0;
    return out;
  });

  if (!recordId) {
    const ins = await traced('insertRecord', `Investor_Pricing (new, ${accountId})`, () =>
      ZOHO.CRM.API.insertRecord({
        Entity: 'Investor_Pricing',
        APIData: {
          Investor: { id: String(accountId) },
          Pricing_Year: yr,
          Investor_Pricing_Status: 'Active',
          Investor_Pricing_Matrix: matrix,
        },
        Trigger: ['workflow'],
      })
    );
    const first = ins?.data?.[0];
    if (first?.code !== 'SUCCESS') {
      throw new Error('Pricing record create failed: ' + (first?.message || JSON.stringify(ins).slice(0, 200)));
    }
    return { recordId: first.details?.id, created: true, rowCount: matrix.length };
  }

  const upd = await traced('updateRecord', `Investor_Pricing ${recordId} matrix`, () =>
    ZOHO.CRM.API.updateRecord({
      Entity: 'Investor_Pricing',
      APIData: { id: String(recordId), Investor_Pricing_Matrix: matrix },
      Trigger: ['workflow'],
    })
  );
  if (upd?.data?.[0]?.code !== 'SUCCESS') {
    throw new Error('Pricing matrix update failed: ' + (upd?.data?.[0]?.message || JSON.stringify(upd).slice(0, 200)));
  }
  return { recordId: String(recordId), created: false, rowCount: matrix.length };
}

export async function createTranche(payload) {
  return write(`Create Tranche "${payload.Name}" with ${payload.dealIds.length} deals`, async () =>
    (await sdk()).CRM.API.insertRecord({
      Entity: 'Tranches',
      APIData: {
        Name: payload.Name,
        Investor: { id: String(payload.investorId) },
        Tranche_Date: payload.trancheDate,
        Tranche_Status: 'Open',
      },
      Trigger: ['workflow'],
    })
  );
}

export async function lockTranche(trancheId) {
  return write(
    `Lock tranche ${trancheId} — runs finalizeTranche5: sets Avail_for_Purchase=false on ` +
      `every deal, Tranche_Status="Locked", emails 3 recipients, snapshots to Tranche_Logs`,
    async () =>
      (await sdk()).CRM.FUNCTIONS.execute('finalizeTranche5', {
        arguments: JSON.stringify({ trancheId }),
      })
  );
}
